function getMcafeeMvisionTranslation(key, lang) {
    return (mcafeemvisionTranslations[lang] && mcafeemvisionTranslations[lang][key]) ||
           (mcafeemvisionTranslations.en && mcafeemvisionTranslations.en[key]) || null;
}

function applyMcafeeMvisionTranslations(lang) {
    let count = 0;
    document.querySelectorAll("[data-i18n]").forEach(el => {
        const key = el.getAttribute("data-i18n");
        if (key && (key.startsWith("review.mcafee-mvision.") || key.startsWith("review.common."))) {
            const translation = getMcafeeMvisionTranslation(key, lang);
            if (translation) { el.textContent = translation; count++; }
        }
    });
    console.log(`Applied ${count} mcafee-mvision translations`);
}

window.addEventListener("languageChanged", e => setTimeout(() => applyMcafeeMvisionTranslations(e.detail.language), 200));

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => applyMcafeeMvisionTranslations(window.i18n?.getCurrentLanguage() || "en"));
} else {
    applyMcafeeMvisionTranslations(window.i18n?.getCurrentLanguage() || "en");
}
